using System.Reflection;
using D47.Core.Journal;

namespace D47.Core.Knowledge;

/// <summary>One event a story step may name; <see cref="Needs"/> and <see cref="Career"/> are empty where none applies.</summary>
public sealed record StepEvent(
    string Source,
    string Event,
    bool Drawable,
    IReadOnlyList<string> Needs,
    string Career,
    string Description);

/// <summary>The events, fields and values a story step may name, generated by <c>tools/gen-step-events.py</c>.</summary>
public sealed class StepEventCatalogue
{
    public const string JournalSource = "journal";

    private const string EventsResource = "D47.Core.StepEvents";
    private const string FieldsResource = "D47.Core.StepFields";

    private static readonly Lazy<StepEventCatalogue> Shipped =
        new(() => Parse(Read(EventsResource), Read(FieldsResource)), LazyThreadSafetyMode.ExecutionAndPublication);

    private readonly Dictionary<string, StepEvent> _events;
    private readonly Dictionary<string, Dictionary<string, HashSet<string>>> _fields;
    private readonly Dictionary<string, HashSet<string>> _drawableValues;

    private StepEventCatalogue(
        Dictionary<string, StepEvent> events,
        Dictionary<string, Dictionary<string, HashSet<string>>> fields,
        Dictionary<string, HashSet<string>> drawableValues)
    {
        _events = events;
        _fields = fields;
        _drawableValues = drawableValues;
    }

    public static StepEventCatalogue Default => Shipped.Value;

    /// <summary>Reads a catalogue from the text of the two tables.</summary>
    public static StepEventCatalogue Parse(string events, string fields)
    {
        var eventRows = new Dictionary<string, StepEvent>(StringComparer.Ordinal);

        foreach (var cells in Rows(events, 6))
        {
            var needs = cells[3].Length == 0 ? [] : cells[3].Split(',');
            eventRows[cells[1]] = new StepEvent(cells[0], cells[1], cells[2] == "yes", needs, cells[4], cells[5]);
        }

        var fieldRows = new Dictionary<string, Dictionary<string, HashSet<string>>>(StringComparer.Ordinal);
        var drawableValues = new Dictionary<string, HashSet<string>>(StringComparer.Ordinal);

        foreach (var cells in Rows(fields, 5))
        {
            if (!fieldRows.TryGetValue(cells[0], out var byField))
            {
                fieldRows[cells[0]] = byField = new Dictionary<string, HashSet<string>>(StringComparer.Ordinal);
            }

            if (!byField.TryGetValue(cells[1], out var values))
            {
                byField[cells[1]] = values = new HashSet<string>(StringComparer.Ordinal);
            }

            if (cells[3].Length == 0)
            {
                continue;
            }

            values.Add(cells[3]);

            if (cells[4] == "yes")
            {
                var key = $"{cells[0]}.{cells[1]}";

                if (!drawableValues.TryGetValue(key, out var drawn))
                {
                    drawableValues[key] = drawn = new HashSet<string>(StringComparer.Ordinal);
                }

                drawn.Add(cells[3]);
            }
        }

        return new StepEventCatalogue(eventRows, fieldRows, drawableValues);
    }

    /// <summary>Whether a step may name the event; a journal event also has to be one d47 acts on.</summary>
    public bool Exists(string? name) =>
        name is not null
        && _events.TryGetValue(name, out var row)
        && (row.Source != JournalSource || HandledEvents.ActedOn.Contains(name));

    /// <summary>The fields a step may name on the event, in name order; none for an event that does not exist.</summary>
    public IReadOnlyList<string> FieldsOf(string? name) =>
        Exists(name) && _fields.TryGetValue(name!, out var byField)
            ? [.. byField.Keys.Order(StringComparer.Ordinal)]
            : [];

    /// <summary>Whether a step may compare the field with the value; a field with no value rows allows none.</summary>
    public bool AllowsValue(string? name, string? field, string? value) =>
        value is not null
        && field is not null
        && Exists(name)
        && _fields.TryGetValue(name!, out var byField)
        && byField.TryGetValue(field, out var values)
        && values.Contains(value);

    /// <summary>The values a step may compare the field with, in order; none where the field allows none.</summary>
    public IReadOnlyList<string> ValuesOf(string? name, string? field) =>
        Exists(name) && field is not null && _fields.TryGetValue(name!, out var byField)
            && byField.TryGetValue(field, out var values)
            ? [.. values.Order(StringComparer.Ordinal)]
            : [];

    /// <summary>The events a story may draw as a step, in name order, each with its gates and career.</summary>
    public IReadOnlyList<StepEvent> Drawable =>
        [.. _events.Values.Where(row => row.Drawable && Exists(row.Event)).OrderBy(row => row.Event, StringComparer.Ordinal)];

    /// <summary>Whether a story may draw the value of the field as a step.</summary>
    public bool IsDrawableValue(string name, string field, string value) =>
        _drawableValues.TryGetValue($"{name}.{field}", out var values) && values.Contains(value);

    /// <summary>The values a story may draw for the field, in order; none where the field has none.</summary>
    public IReadOnlyList<string> DrawableValuesOf(string name, string field) =>
        _drawableValues.TryGetValue($"{name}.{field}", out var values) ? [.. values.Order(StringComparer.Ordinal)] : [];

    private static IEnumerable<string[]> Rows(string text, int columns)
    {
        using var reader = new StringReader(text);

        while (reader.ReadLine() is { } line)
        {
            if (line.Length == 0 || line[0] == '#')
            {
                continue;
            }

            var cells = line.Split('\t');

            if (cells.Length == columns)
            {
                yield return cells;
            }
        }
    }

    private static string Read(string resource)
    {
        using var stream = typeof(StepEventCatalogue).GetTypeInfo().Assembly.GetManifestResourceStream(resource);

        if (stream is null)
        {
            return string.Empty;
        }

        using var reader = new StreamReader(stream);
        return reader.ReadToEnd();
    }
}
